    Label: string;
    Amount: number;
    RunningTotal: number;
}

export interface PreviewPriceOutput {
    Success: boolean;
    Message?: string;
    UnitPrice?: number;
    ExtendedAmount?: number;
    Quantity?: number;
    /** The list that applied, and how it was arrived at. */
    PriceListID?: string | null;
    PriceListName?: string | null;
