SELECT TOP 1 @ID_a4545d7a06ed = [ID] FROM [${mjSchema}].[RemoteOperation] WHERE [OperationKey] = N'Orders.RecordProgress' ORDER BY CASE WHEN [ID] = @ID_a4545d7a06ed THEN 0 ELSE 1 END
SELECT TOP 1 @CategoryID_a4545d7a06ed = [ID] FROM [${mjSchema}].[RemoteOperationCategory] WHERE [Name] = N'Receivables' ORDER BY CASE WHEN [ID] = @CategoryID_a4545d7a06ed THEN 0 ELSE 1 END
EXEC [${mjSchema}].spUpdateRemoteOperation @Name = @Name_a4545d7a06ed,
  @OperationKey = @OperationKey_a4545d7a06ed,
  @CategoryID = @CategoryID_a4545d7a06ed,
  @Description = @Description_a4545d7a06ed,
  @InputTypeName = @InputTypeName_a4545d7a06ed,
  @InputTypeDefinition = @InputTypeDefinition_a4545d7a06ed,
  @InputTypeIsArray = @InputTypeIsArray_a4545d7a06ed,
  @OutputTypeName = @OutputTypeName_a4545d7a06ed,
  @OutputTypeDefinition = @OutputTypeDefinition_a4545d7a06ed,
  @OutputTypeIsArray = @OutputTypeIsArray_a4545d7a06ed,
  @ExecutionMode = @ExecutionMode_a4545d7a06ed,
  @RequiredScope = @RequiredScope_a4545d7a06ed,
  @RequiresSystemUser = @RequiresSystemUser_a4545d7a06ed,
  @GenerationType = @GenerationType_a4545d7a06ed,
