  @UseAuditLog_0dbf70d3d1f6 = 1
SET
  @Description_0dbf70d3d1f6 = N'Replace the latest posted progress observation on a percentage-of-completion line. Orders.RecordProgress writes a new observation that names the one it replaces, reverses the replaced observation''s recognition (on its own date, or on the first open day when finance has closed that month), and posts the new catch-up on the date entered, which may not be in a month finance has closed. Nothing is edited; the replaced row stays Posted and immutable. Held by the Orders Revenue Supervisor role, on top of MJ.BizApps.Orders.Progress.Attest, which every attestation needs. Without this row, supersede is refused.'
